    <script>function posWorkspace(products,customers,labels,currency){return{products,customers,labels,currency,customerId:@js((string) old('customer_id', '')),walkInName:@js(old('walk_in_name', '')),walkInPhone:@js(old('walk_in_phone', '')),cart:[],held:[],search:'',category:'All',barcode:'',scanStatus:'',screen:'pos',get filteredProducts(){let q=this.search.toLowerCase();return this.products.filter(p=>(this.category==='All'||p.category===this.category)&&(!q||p.name.toLowerCase().includes(q)||p.sku.toLowerCase().includes(q)||(p.barcode||'').includes(q)))},add(p){let i=this.cart.find(x=>x.id===p.id);if(i)i.qty++;else this.cart.push({...p,qty:1,discount:0})},remove(i){this.cart.splice(i,1)},changePrice(i){let p=i.prices.find(x=>x.level_id==i.price_level_id);if(p)i.price=p.amount},lineTotal(i){return i.price*i.qty*(1-i.discount/100)},discountAmount(i){return (i.price*i.qty*i.discount/100).toFixed(2)},get subtotal(){return this.cart.reduce((s,i)=>s+i.price*i.qty,0)},get discounts(){return this.cart.reduce((s,i)=>s+i.price*i.qty*i.discount/100,0)},get total(){return this.subtotal-this.discounts},money(v){return this.currency+' '+Number(v).toLocaleString('en-US',{maximumFractionDigits:2})},scan(){let q=this.barcode.trim().toLowerCase(),p=this.products.find(x=>x.sku.toLowerCase()===q||(x.barcode||'').toLowerCase()===q);if(p){this.add(p);this.scanStatus='✓ '+this.labels.added}else this.scanStatus='× '+this.labels.notFound;this.barcode='';setTimeout(()=>this.scanStatus='',1500)},hold(){if(!this.cart.length)return;this.held.push(this.cart.map(x=>({...x})));this.cart=[]},resumeHeld(){if(this.held.length)this.cart=this.held.pop()}}}</script>
    <script>
        function posWorkspace(products, customers, labels, currency) {
            return {
                products, customers, labels, currency,
                customerId: @js((string) old('customer_id', '')),
                walkInName: @js(old('walk_in_name', '')),
                walkInPhone: @js(old('walk_in_phone', '')),
                cart: [], held: [], search: '', category: 'All', barcode: '', scanStatus: '', screen: 'pos', productView: 'cards', salesView: @js(in_array(request('sales_view'), ['cards', 'list'], true) ? request('sales_view') : 'cards'), cartExpanded: false, mobileCartOpen: false, isMobile: window.innerWidth < 1024, customerPickerOpen: false, customerSearch: '', selectedProduct: null, selectedQuantity: 1, selectedPrice: 0,
                init() { window.addEventListener('resize', () => this.isMobile = window.innerWidth < 1024); },
                get filteredProducts() { const query = this.search.toLowerCase(); return this.products.filter(product => (this.category === 'All' || product.category === this.category) && (!query || product.name.toLowerCase().includes(query) || product.sku.toLowerCase().includes(query) || (product.barcode || '').includes(query))); },
                get groupedProducts() { const groups = {}; this.filteredProducts.forEach(product => { (groups[product.category] ??= []).push(product); }); return Object.entries(groups).map(([name, products]) => ({ name, products })); },
                selectProduct(product) { if (this.productView === 'list') { this.add(product); return; } this.selectedProduct = product; this.selectedQuantity = 1; this.selectedPrice = Number(product.price); },
                clearSelectedProduct() { this.selectedProduct = null; this.selectedQuantity = 1; this.selectedPrice = 0; },
                addSelectedProduct() { if (!this.selectedProduct || Number(this.selectedQuantity) <= 0 || Number(this.selectedPrice) < 0) return; const item = this.cart.find(cartItem => cartItem.id === this.selectedProduct.id && Number(cartItem.price) === Number(this.selectedPrice)); if (item) { item.qty += Number(this.selectedQuantity); } else { this.cart.push({ ...this.selectedProduct, price: Number(this.selectedPrice), qty: Number(this.selectedQuantity), adjustmentDirection: 'discount', adjustmentType: 'percent', adjustmentValue: 0, overrideReason: '' }); } this.clearSelectedProduct(); },
                add(product) { const item = this.cart.find(cartItem => cartItem.id === product.id); if (item) { item.qty++; } else { this.cart.push({ ...product, qty: 1, adjustmentDirection: 'discount', adjustmentType: 'percent', adjustmentValue: 0, overrideReason: '' }); } },
                remove(index) { this.cart.splice(index, 1); },
                changePrice(item) { const price = item.prices.find(candidate => candidate.level_id == item.price_level_id); if (price) item.price = price.amount; },
                changeAdjustment(item, step) { const increment = item.adjustmentType === 'percent' ? 1 : 500; item.adjustmentValue = Math.max(0, Number(item.adjustmentValue || 0) + (step * increment)); },
                effectiveUnitPrice(item) { const value = Number(item.adjustmentValue || 0); return item.adjustmentDirection === 'increase' ? Number(item.price) + (item.adjustmentType === 'percent' ? Number(item.price) * value / 100 : value) : Number(item.price); },
                lineSubtotal(item) { return this.effectiveUnitPrice(item) * Number(item.qty); },
                discountAmount(item) { if (item.adjustmentDirection !== 'discount') return '0.00'; const gross = this.lineSubtotal(item); const value = Number(item.adjustmentValue || 0); return Math.min(gross, item.adjustmentType === 'percent' ? gross * value / 100 : value).toFixed(2); },
                lineTotal(item) { return this.lineSubtotal(item) - Number(this.discountAmount(item)); },
                get subtotal() { return this.cart.reduce((sum, item) => sum + this.lineSubtotal(item), 0); },
                get discounts() { return this.cart.reduce((sum, item) => sum + Number(this.discountAmount(item)), 0); },
                get total() { return this.subtotal - this.discounts; },
                get shortageItems() { return this.cart.filter(item => Number(item.qty) > Number(item.stock)); },
                money(value) { return this.currency+' '+Number(value).toLocaleString('en-US', { maximumFractionDigits: 2 }); },
                scan() { const query = this.barcode.trim().toLowerCase(); const product = this.products.find(item => item.sku.toLowerCase() === query || (item.barcode || '').toLowerCase() === query); if (product) { this.add(product); this.scanStatus = '✓ '+this.labels.added; } else this.scanStatus = '× '+this.labels.notFound; this.barcode = ''; setTimeout(() => this.scanStatus = '', 1500); },
                hold() { if (!this.cart.length) return; this.held.push(this.cart.map(item => ({ ...item }))); this.cart = []; },
                resumeHeld() { if (this.held.length) this.cart = this.held.pop(); },
            };
        }
    </script>
